    const k = `${canonicalCourseCode(`${w.prefix} ${w.course_number}`)}|${_verNormSec(w.section)}|${_owlProgram(w) === "online" ? "online" : "semester"}|${_owlIsLab(w) ? 1 : 0}`;
    if(!owlCredits.has(k)) owlCredits.set(k, w.credits != null ? Number(w.credits) : null);
